const e={web3_267:{lianjieqianbao:"Connecter le Portefeuille",wodeqianbaodizhi:"Mon Adresse de Portefeuille",licai:"Minage",jinrulicai:"Entrer dans le Minage",yishouyi:"Revenus Obtenus",shouyilv:"Taux de Rendement",zhiyajine:"Montant du Minage",canyu:"Participer",shouyishijian:"Temps de Revenus {amount}/{time}",yifafangshouyi:"Revenus Distribués",licaishuju:"Données de Minage",zongchanliang:"Production Totale",youxiaojiedian:"Nœuds Valides",canyuzhe:"Participants",yonghushouru:"Revenus Utilisateurs",liudongxinglicaishouyi:"Revenus du Minage de Liquidité",shouyi:"Revenus",licaishuoming:"Explication du Minage",weishenmeyaolicai:"Pourquoi miner ?",weishenmeyaolicai_desc:"Le minage est le processus d’augmentation des actifs en allouant les fonds de manière raisonnable et en utilisant divers outils financiers. Un minage efficace peut contrer l’inflation, augmenter les revenus passifs, atteindre la liberté financière et réaliser une retraite anticipée.",licaifengxian:"Quels sont les risques du minage ?",licaifengxian_desc:"Les risques du minage incluent le risque de marché, le risque d’inflation, le risque de liquidité, le risque de crédit et le risque opérationnel. Les investisseurs doivent choisir des produits adaptés selon leur tolérance au risque et diversifier leurs actifs pour réduire les risques.",xinshoruhekaishilicai:"Comment les débutants peuvent-ils commencer le minage ?",xinshoruhekaishilicai_desc:"Les débutants devraient d’abord constituer un fonds d’urgence, comprendre leur situation financière, fixer des objectifs, acquérir des connaissances de base en investissement, commencer par des produits à faible risque, élargir progressivement leur portefeuille et continuer à apprendre et à ajuster leurs stratégies.",qukuailianlicai_youshi:"Quels sont les avantages du minage blockchain ?",qukuailianlicai_youshi_desc:"Le minage blockchain présente des avantages tels que la décentralisation, une transparence élevée, de faibles coûts de transaction, une accessibilité mondiale et l’exécution automatique des contrats intelligents, offrant des solutions innovantes au marché minier traditionnel.",liudongxingzhiyashishenme:"Qu’est-ce que le minage de liquidité ?",liudongxingzhiyashishenme_desc:"Le minage de liquidité est le processus consistant à verrouiller des actifs cryptographiques dans un protocole DeFi afin de fournir de la liquidité tout en recevant des récompenses. Les mineurs reçoivent généralement une part des frais de transaction et des jetons de gouvernance, ce qui en fait une méthode populaire de revenu passif.",ruhepinggulicaichanpindefengxian:"Comment évaluer les risques des produits de minage ?",ruhepinggulicaichanpindefengxian_desc:"Pour évaluer les risques des produits de minage, il faut prendre en compte la volatilité des revenus, les performances historiques, la liquidité, la réputation de l’émetteur, la durée de l’investissement et l’environnement du marché, tout en tenant compte de sa propre tolérance au risque.",shouyibiao:"Tableau des Revenus",meirishouyi:"Revenus Quotidiens"},licai:{zhiyawakuang:"Finance IA",zhiyawakuangjiaoyi:"Finance IA"}};export{e as default};
